script:
frappe.ui.form.on("Stock Entry", {
    refresh(frm) {
        // Do not update Item storage locations from the browser.
        // The server-side hook handles this on submission.

        if (frm.doc.docstatus === 1) {
            frm.dashboard.set_headline(
                __("Item storage locations are updated by the server.")
            );
        }
    },

    validate(frm) {
        // Validate storage-location rows before saving/submitting.
        const rows = frm.doc.custom_storage_location || [];

        for (const row of rows) {
            if (row.item && !row.warehouse) {
                frappe.throw(
                    __("Please select a Warehouse for Item {0}.", [
                        row.item
                    ])
                );
            }
        }
    }
});

frappe.ui.form.on('Box Entry', {
  after_save(frm) {
    if (frm.doc.box_number !== frm.doc.name) {
      frm.set_value('box_number', frm.doc.name).then(() => frm.save());
    }
  }
});

// Purchase Order: fill custom_full_items (PO Full Item) from the rows in the items table
var TARGET_TABLE = 'custom_full_items';
var SOURCE_TABLE = 'items';
var BOX_DEBUG = false;

frappe.ui.form.on('Purchase Order Item', {
    item_code: function (frm, cdt, cdn) {
        if (is_source_row(cdt, cdn)) queue_rebuild(frm);
    },
    qty: function (frm, cdt, cdn) {
        if (is_source_row(cdt, cdn)) queue_rebuild(frm);
    }
});

frappe.ui.form.on('Purchase Order', {
    items_remove: function (frm) {
        queue_rebuild(frm);
    }
});

function step(msg, color) {
    console.log('BOX SCRIPT: ' + msg);
    if (BOX_DEBUG || color === 'red' || color === 'orange') {
        frappe.show_alert({ message: msg, indicator: color || 'blue' }, 8);
    }
}

function wait(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
}

function load_doctype(dt) {
    return new Promise(function (resolve) {
        frappe.model.with_doctype(dt, function () { resolve(); });
    });
}

function is_source_row(cdt, cdn) {
    var row = locals[cdt] && locals[cdt][cdn];
    return !!row && row.parentfield === SOURCE_TABLE;
}

function queue_rebuild(frm) {
    clearTimeout(frm.__box_timer);
    frm.__box_timer = setTimeout(function () {
        build_full_items(frm);
    }, 1200);
}

function get_is_box(item) {
    var meta = frappe.get_meta('Item');
    if (!meta) return null;
    var f = meta.fields.find(function (x) {
        var label = (x.label || '').toLowerCase().replace(/\s+/g, ' ').trim();
        return x.fieldtype === 'Check' &&
            (label === 'is box item' || (x.fieldname || '').indexOf('is_box') > -1);
    });
    if (!f) return null;
    return cint(item[f.fieldname]) === 1;
}

function find_box_rows(item) {
    var meta = frappe.get_meta('Item');
    var tables = meta ? meta.fields.filter(function (f) {
        return f.fieldtype === 'Table';
    }) : [];

    var f = tables.find(function (x) { return x.options === 'Box Items'; });
    if (f && (item[f.fieldname] || []).length) return item[f.fieldname];

    f = tables.find(function (x) {
        return (x.fieldname || '').indexOf('box') > -1 ||
            (x.label || '').toLowerCase().indexOf('box') > -1;
    });
    if (f && (item[f.fieldname] || []).length) return item[f.fieldname];

    var keys = Object.keys(item);
    for (var i = 0; i < keys.length; i++) {
        var v = item[keys[i]];
        if (Array.isArray(v) && v.length && v[0] && v[0].doctype === 'Box Items') return v;
    }
    return [];
}

// finds the real fieldnames of the Full Items child table
function get_full_fields() {
    var df = frappe.meta.get_docfield('Purchase Order', TARGET_TABLE);
    if (!df) return Promise.resolve({});
    return load_doctype(df.options).then(function () {
        var meta = frappe.get_meta(df.options);
        var fields = meta ? meta.fields : [];

        var has = function (x, words) {
            var s = ((x.fieldname || '') + ' ' + (x.label || '')).toLowerCase();
            return words.some(function (w) { return s.indexOf(w) > -1; });
        };
        var isItemLink = function (x) { return x.fieldtype === 'Link' && x.options === 'Item'; };

        var box = fields.find(function (x) { return isItemLink(x) && has(x, ['box']); });
        var item = fields.find(function (x) { return isItemLink(x) && x !== box; }) ||
                   fields.find(function (x) { return ['item', 'item_code'].indexOf(x.fieldname) > -1; });
        var name = fields.find(function (x) { return x.fieldtype === 'Data' && has(x, ['name']); });
        var qty = fields.find(function (x) { return ['Float', 'Int'].indexOf(x.fieldtype) > -1 && has(x, ['qty', 'quantity']); }) ||
                  fields.find(function (x) { return ['Float', 'Int'].indexOf(x.fieldtype) > -1; });
        var uom = fields.find(function (x) { return x.fieldtype === 'Link' && x.options === 'UOM'; });

        return {
            item: item && item.fieldname,
            name: name && name.fieldname,
            qty: qty && qty.fieldname,
            uom: uom && uom.fieldname,
            box: box && box.fieldname,
            all: fields.map(function (x) { return x.fieldname; }).join(', ')
        };
    });
}

function get_item(cache, code) {
    if (cache[code]) return Promise.resolve(cache[code]);
    return Promise.resolve(frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Item', name: code }
    })).then(function (r) {
        cache[code] = r.message;
        return r.message;
    });
}

function get_info(cache, code) {
    if (cache[code]) return Promise.resolve(cache[code]);
    return Promise.resolve(
        frappe.db.get_value('Item', code, ['item_name', 'stock_uom'])
    ).then(function (r) {
        cache[code] = (r && r.message) || {};
        return cache[code];
    });
}

function add_full_row(frm, f, d) {
    var row = {};
    row[f.item] = d.item_code;
    if (f.name) row[f.name] = d.item_name;
    if (f.qty) row[f.qty] = d.qty;
    if (f.uom) row[f.uom] = d.uom;
    if (f.box && d.source_box) row[f.box] = d.source_box;
    frm.add_child(TARGET_TABLE, row);
}

function set_supplier_if_empty(frm, item) {
    if (frm.doc.supplier) return Promise.resolve();
    var supplier = item.supplier;
    if (!supplier) {
        var si = (item.supplier_items || []).filter(function (d) { return d.supplier; });
        if (si.length) supplier = si[0].supplier;
    }
    if (supplier) return Promise.resolve(frm.set_value('supplier', supplier));
    return Promise.resolve();
}

// add the parts of a box one by one
function add_box_parts(ctx, item, box_rows, src_qty, i) {
    if (i >= box_rows.length) return Promise.resolve();
    var b = box_rows[i];
    var code = b[ctx.linkName] || b.item || b.item_code;
    if (!code) return add_box_parts(ctx, item, box_rows, src_qty, i + 1);
    return get_info(ctx.info_cache, code).then(function (info) {
        add_full_row(ctx.frm, ctx.f, {
            item_code: code,
            item_name: info.item_name,
            qty: flt(b.quantity || b.qty || 1) * src_qty,
            uom: b.uom || info.stock_uom,
            source_box: item.name
        });
        ctx.added++;
        return add_box_parts(ctx, item, box_rows, src_qty, i + 1);
    });
}

// handle one row of the items table
function process_row(ctx, src) {
    var frm = ctx.frm;
    var src_qty = flt(src.qty) || 1;
    return get_item(ctx.item_cache, src.item_code).then(function (item) {
        if (!item) {
            step('Could not read the Item ' + src.item_code, 'red');
            return;
        }
        return set_supplier_if_empty(frm, item).then(function () {
            var box_rows = find_box_rows(item);
            var is_box = get_is_box(item);
            if (is_box === null) is_box = box_rows.length > 0;

            if (is_box && box_rows.length) {
                return add_box_parts(ctx, item, box_rows, src_qty, 0);
            }
            if (is_box) {
                step('Is Box Item is ticked but no Box Items found on ' + (item.item_name || item.name), 'orange');
            }
            return get_info(ctx.info_cache, item.name).then(function (info) {
                add_full_row(frm, ctx.f, {
                    item_code: item.name,
                    item_name: info.item_name,
                    qty: src_qty,
                    uom: src.uom || info.stock_uom
                });
                ctx.added++;
            });
        });
    });
}

function process_rows(ctx, rows, idx) {
    if (idx >= rows.length) return Promise.resolve();
    return process_row(ctx, rows[idx]).then(function () {
        return process_rows(ctx, rows, idx + 1);
    });
}

function build_full_items(frm) {
    if (frm.__loading_box) {
        frm.__box_pending = true;
        return;
    }
    frm.__loading_box = true;
    frm.__box_pending = false;

    var ctx = { frm: frm, f: null, item_cache: {}, info_cache: {}, added: 0, linkName: 'item' };

    load_doctype('Item')
        .then(function () { return load_doctype('Box Items'); })
        .then(function () { return get_full_fields(); })
        .then(function (f) {
            ctx.f = f;
            if (!f.item) {
                step('Full Items table: no Item field found. Fields: ' + (f.all || 'none'), 'red');
                return;
            }

            var source_rows = (frm.doc[SOURCE_TABLE] || []).filter(function (r) { return r.item_code; });

            frm.clear_table(TARGET_TABLE);

            if (!source_rows.length) {
                frm.refresh_field(TARGET_TABLE);
                return;
            }

            var boxMeta = frappe.get_meta('Box Items');
            var linkField = boxMeta ? boxMeta.fields.find(function (x) {
                return x.fieldtype === 'Link' && x.options === 'Item';
            }) : null;
            ctx.linkName = linkField ? linkField.fieldname : 'item';

            return process_rows(ctx, source_rows, 0).then(function () {
                frm.refresh_field(TARGET_TABLE);
                frappe.show_alert({
                    message: 'Full Items updated (' + ctx.added + ' rows)',
                    indicator: 'green'
                });
            });
        })
        .catch(function (e) {
            console.error(e);
            step('FAILED: ' + ((e && e.message) || e), 'red');
        })
        .then(function () { return wait(300); })
        .then(function () {
            frm.__loading_box = false;
            if (frm.__box_pending) {
                frm.__box_pending = false;
                queue_rebuild(frm);
            }
        });
}
// END OF SCRIPT

frappe.ui.form.on("Service Entry", {
    vehicle_number: async function(frm) {
        if (!frm.doc.vehicle_number) {
            await frm.set_value("item", "");
            await frm.set_value("brand", "");
            await frm.set_value("item_group", "");
            return;
        }

        try {
            const response = await frappe.call({
                method: "byky_app.vehicle_service.get_vehicle_details",
                args: {
                    serial_no: frm.doc.vehicle_number
                }
            });

            if (response.message) {
                await frm.set_value("item", response.message.item || "");
                await frm.set_value("brand", response.message.brand || "");
                await frm.set_value("item_group", response.message.item_group || "");
            }
        } catch (error) {
            console.error("Vehicle details error:", error);

            frappe.msgprint({
                title: __("Vehicle Details Error"),
                indicator: "red",
                message: __("Could not retrieve vehicle details. Check the Error Log.")
            });
        }
    }
});

frappe.ui.form.on('Vehicle Tear Down', {
    item: async function(frm) {
        // Clear the existing recovered-parts rows
        frm.clear_table('recovered_parts');

        if (!frm.doc.item) {
            frm.refresh_field('recovered_parts');
            return;
        }

        // Fetch the selected Item document
        const item_doc = await frappe.db.get_doc(
            'Item',
            frm.doc.item
        );

        // Copy the configured Box Items
        (item_doc.custom_box_items || []).forEach(box => {
            const row = frm.add_child('recovered_parts');

            row.item_code = box.item;
            row.quantity = 1;
        });

        frm.refresh_field('recovered_parts');
    }
});

(function () {

    // --------------------------------------------------
    // CONFIGURATION
    // --------------------------------------------------

    var TABLE = 'custom_storage_location';
    var FLAG = 'custom_is_warehouse_storage';
    var SAME_LOCATION_FLAG = 'custom_same_location';

    var F = {
        item: 'item',
        warehouse: 'warehouse',
        floor: 'floor',
        area: 'area',
        shelf: 'shelf',
        rack: 'rack',
        uom: 'uom',
        qty: 'quantity'
    };

    var LOCATION_FIELDS = [
        F.warehouse,
        F.floor,
        F.area,
        F.shelf,
        F.rack
    ];

    var SKIP = [
        'name',
        'owner',
        'creation',
        'modified',
        'modified_by',
        'docstatus',
        'idx',
        'parent',
        'parentfield',
        'parenttype',
        'doctype',
        '__islocal',
        '__unsaved'
    ];

    // --------------------------------------------------
    // STOCK ENTRY EVENTS
    // --------------------------------------------------

    frappe.ui.form.on('Stock Entry', {

        refresh: function (frm) {
            queue_sync(frm);
        },

        custom_is_warehouse_storage: function (frm) {

            if (frm.doc[FLAG]) {
                return;
            }

            queue_sync(frm);
        },

        custom_same_location: function (frm) {

            if (frm.doc[SAME_LOCATION_FLAG]) {
                copy_first_location(frm);
            }
        },

        items_remove: function (frm) {
            queue_sync(frm);
        },

        validate: function (frm) {

            if (!frm.doc[FLAG]) {
                sync_target_warehouses(frm);
            }

            validate_target_warehouse(frm);
        }
    });

    // --------------------------------------------------
    // STOCK ENTRY DETAIL EVENTS
    // --------------------------------------------------

    frappe.ui.form.on('Stock Entry Detail', {

        item_code: function (frm) {
            queue_sync(frm);
        },

        qty: function (frm) {
            queue_sync(frm);
        },

        s_warehouse: function (frm) {
            queue_sync(frm);
        },

        t_warehouse: function (frm) {
            queue_sync(frm);
        },

        uom: function (frm) {
            queue_sync(frm);
        }
    });

    // --------------------------------------------------
    // STORAGE LOCATION CHILD EVENTS
    // --------------------------------------------------

    frappe.ui.form.on('Stock Entry Storage Location', {

        item: function (frm) {

            if (!frm.doc[FLAG]) {
                sync_target_warehouses(frm);
            }
        },

        warehouse: function (frm, cdt, cdn) {

            if (frm.doc[SAME_LOCATION_FLAG]) {
                copy_if_first_row(frm, cdn);
            }

            if (!frm.doc[FLAG]) {
                sync_target_warehouses(frm);
            }
        },

        floor: function (frm, cdt, cdn) {
            copy_if_first_row(frm, cdn);
        },

        area: function (frm, cdt, cdn) {
            copy_if_first_row(frm, cdn);
        },

        shelf: function (frm, cdt, cdn) {
            copy_if_first_row(frm, cdn);
        },

        rack: function (frm, cdt, cdn) {
            copy_if_first_row(frm, cdn);
        }
    });

    // --------------------------------------------------
    // DELAY SYNCHRONIZATION
    // --------------------------------------------------

    function queue_sync(frm) {

        if (frm.doc.docstatus !== 0) {
            return;
        }

        clearTimeout(frm.__loc_timer);

        frm.__loc_timer = setTimeout(function () {
            sync_locations(frm);
        }, 800);
    }

    // --------------------------------------------------
    // GENERATE STORAGE LOCATION ROWS
    // ONE ROW PER WHOLE UNIT
    // --------------------------------------------------

    function sync_locations(frm) {

        if (frm.doc.docstatus !== 0) {
            return;
        }

        // Checked means ordinary warehouse storage.
        if (frm.doc[FLAG]) {
            return;
        }

        var wanted = [];
        var counts = {};

        (frm.doc.items || []).forEach(function (d) {

            if (!d.item_code) {
                return;
            }

            // Do not require Target Warehouse to be populated
            // before creating Storage Location rows.
            var warehouse = d.t_warehouse || '';

            var qty = Math.max(0, Math.floor(flt(d.qty)));

            for (var i = 0; i < qty; i++) {

                counts[d.item_code] =
                    (counts[d.item_code] || 0) + 1;

                wanted.push({
                    key: d.item_code + '#' + counts[d.item_code],
                    item: d.item_code,
                    warehouse: warehouse,
                    uom: d.stock_uom || d.uom || '',
                    quantity: 1
                });
            }
        });

        var rows = frm.doc[TABLE] || [];
        var kept = {};
        var seen = {};

        // Preserve existing location details where possible.
        rows.forEach(function (r) {

            var item = r[F.item];

            seen[item] = (seen[item] || 0) + 1;

            var values = {};

            Object.keys(r).forEach(function (field) {

                if (SKIP.indexOf(field) === -1) {
                    values[field] = r[field];
                }
            });

            kept[item + '#' + seen[item]] = values;
        });

        // Avoid rebuilding rows if they already match.
        var unchanged =
            rows.length === wanted.length &&
            wanted.every(function (w, i) {

                return rows[i][F.item] === w.item &&
                    (rows[i][F.warehouse] || '') === w.warehouse &&
                    flt(rows[i][F.qty]) === 1 &&
                    (rows[i][F.uom] || '') === w.uom;
            });

        if (unchanged) {

            if (frm.doc[SAME_LOCATION_FLAG]) {
                copy_first_location(frm);
            }

            return;
        }

        frm.clear_table(TABLE);

        wanted.forEach(function (w) {

            var values = Object.assign({}, kept[w.key] || {});

            // Map the main Item Code to the child Item field.
            values[F.item] = w.item;
            values[F.warehouse] = w.warehouse;
            values[F.uom] = w.uom;
            values[F.qty] = 1;

            frm.add_child(TABLE, values);
        });

        frm.refresh_field(TABLE);

        if (frm.doc[SAME_LOCATION_FLAG]) {
            copy_first_location(frm);
        }

        sync_target_warehouses(frm);
    }

    // --------------------------------------------------
    // STORAGE LOCATION WAREHOUSE TO TARGET WAREHOUSE
    // --------------------------------------------------

    function sync_target_warehouses(frm) {

        if (frm.doc.docstatus !== 0) {
            return;
        }

        // Mapping applies only when the checkbox is unchecked.
        if (frm.doc[FLAG]) {
            return;
        }

        var locations = frm.doc[TABLE] || [];
        var items = frm.doc.items || [];

        items.forEach(function (item_row) {

            if (!item_row.item_code) {
                return;
            }

            // Find a storage row for this item that has a Warehouse.
            var location = locations.find(function (location_row) {

                return location_row[F.item] === item_row.item_code &&
                    !!location_row[F.warehouse];
            });

            if (location) {
                item_row.t_warehouse = location[F.warehouse];
            }
        });

        frm.refresh_field('items');
    }

    // --------------------------------------------------
    // VALIDATE TARGET WAREHOUSE
    // --------------------------------------------------

    function validate_target_warehouse(frm) {

        if (frm.doc.stock_entry_type !== 'Material Transfer') {
            return;
        }

        var missing = [];

        (frm.doc.items || []).forEach(function (row) {

            if (row.item_code && !row.t_warehouse) {
                missing.push(row.idx);
            }
        });

        if (missing.length) {

            frappe.throw(
                __(
                    'Please select a Warehouse in the Storage Location table for item row(s): {0}',
                    [missing.join(', ')]
                )
            );
        }
    }

    // --------------------------------------------------
    // COPY LOCATION WHEN FIRST ROW CHANGES
    // --------------------------------------------------

    function copy_if_first_row(frm, cdn) {

        if (!frm.doc[SAME_LOCATION_FLAG]) {
            return;
        }

        var rows = frm.doc[TABLE] || [];

        if (!rows.length || rows[0].name !== cdn) {
            return;
        }

        copy_first_location(frm);
    }

    // --------------------------------------------------
    // COPY FIRST ROW LOCATION TO REMAINING ROWS
    // --------------------------------------------------

    function copy_first_location(frm) {

        if (!frm.doc[SAME_LOCATION_FLAG]) {
            return;
        }

        var rows = frm.doc[TABLE] || [];

        if (!rows.length) {
            return;
        }

        var first = rows[0];

        rows.forEach(function (row, index) {

            if (index === 0) {
                return;
            }

            LOCATION_FIELDS.forEach(function (field) {
                row[field] = first[field] || '';
            });
        });

        frm.refresh_field(TABLE);

        if (!frm.doc[FLAG]) {
            sync_target_warehouses(frm);
        }
    }

})();

// ==================================================
// SAVE PREVIOUS LOCATIONS FOR CHECKBOX RESTORATION
// ==================================================

let previous_target_locations = {};
let previous_same_item_locations = {};
let previous_wip_locations = {};
let target_update_token = 0;
let target_poll_running = false;


// ==================================================
// LOCATION TABLE CONFIGURATION
// ==================================================

const SOURCE_TABLE = "custom_source_warehouse_storage_location";
const WIP_TABLE = "custom_workinprogress_warehouse_storage_location";
const TARGET_TABLE = "custom_target_warehouse_storage_location";

const LOCATION_TABLES = [SOURCE_TABLE, WIP_TABLE, TARGET_TABLE];

const LOCATION_FIELDS = [
    "warehouse",
    "floor",
    "area",
    "shelf",
    "rack"
];

const registered_row_doctypes = {};


// ==================================================
// WORK ORDER EVENTS
// ==================================================

frappe.ui.form.on("Work Order", {
    setup(frm) {
        register_location_row_events();
    },

    // Page open
    onload(frm) {
        wait_and_update_target_locations(frm);
    },

    // Page fully rendered
    onload_post_render(frm) {
        wait_and_update_target_locations(frm);
    },

    // Production Item
    production_item(frm) {
        update_target_locations(frm);
    },

    // Quantity
    qty(frm) {
        update_target_locations(frm);
        wait_and_update_material_locations(frm);
    },

    // BOM
    bom_no(frm) {
        wait_and_update_material_locations(frm);
    },

    // Source Warehouse -> Source Warehouse Storage Location table
    source_warehouse(frm) {
        update_material_locations(frm);
        apply_header_warehouse(
            frm,
            SOURCE_TABLE,
            frm.doc.source_warehouse,
            true
        );
    },

    // Work-in-Progress Warehouse -> WIP Storage Location table
    wip_warehouse(frm) {
        update_material_locations(frm);
        apply_header_warehouse(
            frm,
            WIP_TABLE,
            frm.doc.wip_warehouse,
            true
        );
    },

    // Finished Goods (Target) Warehouse -> Target Storage Location table
    fg_warehouse(frm) {
        apply_target_warehouse(frm, true);
    },

    // Same Storage for All Items
    custom_same_storage_for_all_item(frm) {
        if (frm.doc.custom_same_storage_for_all_item) {
            save_previous_same_item_locations(frm);
            fill_same_item_locations(frm);
        } else {
            restore_previous_same_item_locations(frm);
        }
    },

    // Same Storage Location Checkbox
    // Only copies the first row's location to all target rows.
    // Rows themselves are already filled when the page opens.
    async custom_same_stroage_location(frm) {
        if (frm.doc.custom_same_stroage_location) {
            save_previous_target_locations(frm);
            copy_first_target_location_to_all(frm);
        } else {
            restore_previous_target_locations(frm);
            await update_target_locations(frm);
        }
    },

    // Same Warehouse Checkbox
    // Ticked   -> save current WIP locations, copy source locations to WIP
    // Unticked -> restore the WIP locations as they were before
    custom_same_warehouse(frm) {
        if (frm.doc.custom_same_warehouse) {
            save_previous_wip_locations(frm);
            copy_source_locations_to_wip(frm);
        } else {
            restore_previous_wip_locations(frm);
        }
    },

    // Before save: push Source table warehouses to Required Items
    before_save(frm) {
        sync_required_item_warehouses(frm);
    },

    // Refresh
    refresh(frm) {
        register_location_row_events();

        if (frm.doc.docstatus !== 0) {
            return;
        }

        wait_and_update_target_locations(frm);

        // Build Source / WIP tables only when new or empty,
        // so a saved Work Order is not marked "Not Saved" again
        if (
            frm.doc.required_items?.length &&
            (frm.is_new() ||
                !(frm.doc[SOURCE_TABLE] || []).length ||
                !(frm.doc[WIP_TABLE] || []).length)
        ) {
            update_material_locations(frm);
        }

        // Fill any blank Warehouse cells from the header warehouses
        apply_header_warehouse(
            frm,
            SOURCE_TABLE,
            frm.doc.source_warehouse,
            false
        );
        apply_header_warehouse(
            frm,
            WIP_TABLE,
            frm.doc.wip_warehouse,
            false
        );

        // Fill blank Source table warehouses from Required Items
        apply_required_item_warehouse(frm);

        if (frm.doc.custom_same_storage_for_all_item) {
            fill_same_item_locations(frm);
        }
    }
});


