    },

    stock_entry_type(frm) {
        fill_from_work_order(frm);
    }
});


// Which Work Order tables feed this Stock Entry type
function get_tables_for_entry_type(entry_type) {
    if (entry_type === "Material Transfer for Manufacture") {
        return [SOURCE_TABLE];
    }

    if (entry_type === "Manufacture") {
        return [MANUFACTURE_RAW_TABLE, TARGET_TABLE];
    }

    return [];
}


// Waits for the Storage Location rows to exist (up to 10s),
// then fills them from the Work Order location tables.
async function fill_from_work_order(frm, attempt = 0) {
    const tables = get_tables_for_entry_type(frm.doc.stock_entry_type);

    if (frm.doc.docstatus !== 0 || !frm.doc.work_order || !tables.length) {
        return;
    }

    if (!(frm.doc[STOCK_ENTRY_TABLE] || []).length) {
        if (attempt < 20) {
            setTimeout(() => fill_from_work_order(frm, attempt + 1), 500);
        }
        return;
    }

    const work_order = await frappe.db.get_doc("Work Order", frm.doc.work_order);

    // Group Work Order rows by item, keeping their order
    const by_item = {};

    tables.forEach(table => {
        (work_order[table] || []).forEach(row => {
            if (!row.item) {
                return;
            }
            (by_item[row.item] = by_item[row.item] || []).push(row);
        });
    });

    const item_index = {};
    let changed = false;

    (frm.doc[STOCK_ENTRY_TABLE] || []).forEach(row => {
        const list = by_item[row.item];

        if (!list || !list.length) {
            return;
        }

        const index = item_index[row.item] || 0;
        item_index[row.item] = index + 1;

        // Use the matching row, or the last one if there are fewer
        const source = list[Math.min(index, list.length - 1)];

        FIELDS.forEach(field => {
            const value = source[field] || "";

            // Only fill blank cells, so manual edits are kept
            if (value && !row[field]) {
                row[field] = value;
                changed = true;
            }
        });
    });

    if (changed) {
        frm.refresh_field(STOCK_ENTRY_TABLE);
    }
}

})();

frappe.listview_settings["Item"] = frappe.listview_settings["Item"] || {};

(function () {
    const settings = frappe.listview_settings["Item"];
    const old_onload = settings.onload;
    const old_refresh = settings.refresh;

    function open_storage_page() {
        window.open("/item-storage-location", "_blank");
    }

    function add_storage_button(listview) {
        // Add only once per list view
        if (listview.__storage_button_added) {
            return;
        }
        listview.__storage_button_added = true;

        listview.page.add_inner_button(__("Storage"), open_storage_page);
        listview.page.add_menu_item(__("Storage"), open_storage_page);
    }

    settings.onload = function (listview) {
        if (old_onload) {
            old_onload.call(this, listview);
        }
        add_storage_button(listview);
    };

    settings.refresh = function (listview) {
        if (old_refresh) {
            old_refresh.call(this, listview);
        }
        add_storage_button(listview);
    };
})();
